export const priceCutDefinitions={
 priceCut:{title:'Compare a lower unit price with the extra volume needed to preserve monthly operating surplus',fields:[
  ['originalPrice','Original selling price per unit (CAD)',100,1,1000,1],
  ['variableCostShare','Variable cost per unit as a share of the original price (%)',60,0,99,1],
  ['baselineUnits','Original monthly unit sales (whole units)',100,0,500,1],
  ['cutPercent','Reduction from the original selling price (%)',20,0,100,1],
  ['discountUnits','Comparison monthly unit sales after the cut (whole units)',150,0,1000,1],
  ['fixedMonthly','Monthly fixed operating costs, unchanged between cases (CAD)',2500,0,50000,100],
  ['capacityUnits','Separate maximum monthly unit capacity assumption',180,0,1000,10]
 ]}
};
export function priceCutPlan(input) {
 const unitCost=input.originalPrice*input.variableCostShare/100,newPrice=input.originalPrice*(1-input.cutPercent/100),originalMargin=input.originalPrice-unitCost,newMargin=newPrice-unitCost;
 const originalRevenue=input.originalPrice*input.baselineUnits,newRevenue=newPrice*input.discountUnits,originalVariable=unitCost*input.baselineUnits,newVariable=unitCost*input.discountUnits;
 const originalContribution=originalMargin*input.baselineUnits,newContribution=newMargin*input.discountUnits,originalSurplus=originalContribution-input.fixedMonthly,newSurplus=newContribution-input.fixedMonthly;
 const exactUnits=originalContribution===0?0:newMargin>1e-9?originalContribution/newMargin:null,requiredUnits=exactUnits==null?null:Math.max(0,Math.ceil(exactUnits-1e-10));
 return {unitCost,newPrice,originalMargin,newMargin,originalRevenue,newRevenue,originalVariable,newVariable,originalContribution,newContribution,originalSurplus,newSurplus,difference:newSurplus-originalSurplus,priceEffect:(newPrice-input.originalPrice)*input.baselineUnits,volumeEffect:(input.discountUnits-input.baselineUnits)*newMargin,exactUnits,requiredUnits,withinCapacity:requiredUnits!=null&&requiredUnits<=input.capacityUnits};
}
export function priceCutResult(kind,input) {
 if(kind!=='priceCut')throw Error('Unknown price-cut topic.');
 const p=priceCutPlan(input),recovery=p.requiredUnits==null?'With positive original contribution and zero or negative contribution per discounted unit, no finite sales volume can preserve the original surplus under these fixed assumptions.':'The minimum whole-unit volume to meet or exceed the original surplus is '+p.requiredUnits.toLocaleString('en-CA')+'. This '+(p.withinCapacity?'fits within':'exceeds')+' the separately entered capacity of '+input.capacityUnits.toLocaleString('en-CA')+' units.';
 const capacity=input.discountUnits>input.capacityUnits?' The selected comparison volume itself exceeds that capacity assumption; its arithmetic result is not feasible under that stated limit.':'';
 const quantities=[...new Set([0,1000,input.baselineUnits,input.discountUnits,input.capacityUnits,...Array.from({length:41},(_,i)=>i*25),...(p.exactUnits!=null&&p.exactUnits<=1000?[p.exactUnits]:[])])].sort((a,b)=>a-b);
 return {metrics:[['Original monthly operating surplus before owner transfers and tax',p.originalSurplus,'money'],['Comparison monthly operating surplus after the price cut',p.newSurplus,'money'],['Minimum whole monthly units to preserve the original surplus',p.requiredUnits,'integer']],note:'Original hypothetical one-product monthly cost-volume model. Variable cost per unit is calculated from the entered share of the original price, then held at '+p.unitCost.toLocaleString('en-CA',{style:'currency',currency:'CAD'})+' through the discount comparison; it is not recalculated as that share of the lower price. The new unit selling price is '+p.newPrice.toLocaleString('en-CA',{style:'currency',currency:'CAD'})+' and contribution per new unit is '+p.newMargin.toLocaleString('en-CA',{style:'currency',currency:'CAD'})+'. Fixed operating costs stay unchanged. '+recovery+capacity+' All selected sales are collected and their variable costs paid in the same month. No sales tax, income tax, debt service, new equipment, inventory timing, receivable delay, extra staffing, tiered costs, demand response or owner withdrawal is included. Operating surplus is not after-tax household income or proof that cash is freely distributable. The volume target preserves the original surplus, which can itself be negative; it is different from breaking even at zero profit. No actual price, capacity or demand estimate is supplied.',charts:[
  {id:'price-cut-revenue-costs',type:'groupbar',title:'Higher revenue can arrive beside a larger increase in variable costs',unit:'money',seriesNames:['Monthly revenue','Monthly variable costs','Monthly fixed operating costs'],rows:[{label:'Original monthly plan',values:[p.originalRevenue,p.originalVariable,input.fixedMonthly]},{label:'Selected discount plan',values:[p.newRevenue,p.newVariable,input.fixedMonthly]}],evidence:'Hypothetical monthly operating comparison',note:'Revenue is unit price × unit count. Variable costs use the same cash cost per unit in both cases, while the fixed-cost input stays unchanged. These bars are parallel amounts, not segments to add together. Revenue less both cost categories gives the separate operating-surplus result. No assumption is made that the lower price causes the selected sales volume.'},
  {id:'price-cut-surplus-bridge',type:'waterfall',title:'Separate the price cut on original units from the contribution on changed volume',unit:'money',rows:[{label:'Original operating surplus',value:p.originalSurplus},{label:'Price change on original units',value:p.priceEffect},{label:'Volume change at the new margin',value:p.volumeEffect}],totalLabel:'Comparison operating surplus',evidence:'Hypothetical exact price-volume bridge',note:'This ordered decomposition first reprices the original unit count, then values the change in units at the new contribution per unit. It reconciles exactly to the comparison surplus without counting the price-volume interaction twice. Reversing the decomposition order would allocate that interaction differently; neither version estimates a causal effect on demand. Unchanged fixed costs cancel in the change.'},
  {id:'price-cut-required-volume',type:'line',title:'The original surplus is a separate target from zero operating profit',unit:'money',xLabel:'Monthly units sold after the cut',series:[{name:'Surplus at each tested discounted volume',rows:quantities.map(x=>({x,value:p.newMargin*x-input.fixedMonthly}))},{name:'Original monthly surplus to preserve',rows:[{x:0,value:p.originalSurplus},{x:1000,value:p.originalSurplus}],dash:true}],evidence:'Hypothetical discounted-volume sensitivity',note:'The curve varies only monthly unit sales at the entered discounted price and unchanged per-unit cost. A feasible continuous equality point is included when it lies within the displayed 0–1,000-unit range; the headline whole-unit target rounds upward. Volumes above the entered capacity are illustrative arithmetic cases outside that capacity assumption. The curve contains no demand forecast or probability weights. With non-positive discounted contribution, extra volume does not restore a positive original contribution.'},
  {id:'price-cut-discount-volume-matrix',type:'heatmap',title:'Test price reductions beside unit volumes instead of assuming revenue growth preserves surplus',unit:'money',signed:true,compactValues:false,columns:[0,10,20,30].map(v=>v+'% cut'),rows:[100,150,200,250].map(discountUnits=>({label:discountUnits+' units',values:[0,10,20,30].map(cutPercent=>priceCutPlan({...input,discountUnits,cutPercent}).difference)})),evidence:'Hypothetical change in monthly surplus',note:'Rows replace monthly comparison units and columns replace the price cut. The original price, original unit count, variable-cost share and fixed costs stay selected inputs. Each cell is comparison surplus minus original surplus. Positive values mean higher surplus and negative values lower. Cells above the entered capacity are arithmetic comparisons, not attainable sales under that assumed capacity. No price elasticity, capacity expansion cost or actual offer is estimated.'}
 ]};
}
